@Injectable()
export class BookingService {
  constructor(private readonly prisma: PrismaService) {}

  async bookRoom(roomId: string, stay: Stay): Promise<Booking> {
    return this.prisma.$transaction(async (tx) => {      // commit on resolve, rollback on throw
      const room = await tx.room.findUniqueOrThrow({ where: { id: roomId } });
      if (!isFree(room, stay)) throw new ConflictException('room unavailable');
      return tx.booking.create({ data: { roomId, ...stay } });
    });
  }
}

async function bookRoom(pool: Pool, roomId: number, stay: Stay): Promise<Booking> {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const { rows } = await client.query<Room>('SELECT * FROM rooms WHERE id = $1 FOR UPDATE', [roomId]);
    if (!rows[0] || !isFree(rows[0], stay)) throw new Error('room unavailable');
    const ins = await client.query<Booking>('INSERT INTO bookings (room_id, from_, to_) VALUES ($1, $2, $3) RETURNING *', [roomId, stay.from, stay.to]);
    await client.query('COMMIT');
    return ins.rows[0];
  } catch (err) { await client.query('ROLLBACK'); throw err; }
  finally { client.release(); }
}

